package ir.ghiyas.alimaa.core.utils

import kotlinx.browser.document
import org.w3c.dom.HTMLAnchorElement
import org.w3c.dom.HTMLInputElement
import org.w3c.dom.url.URL
import org.w3c.files.Blob
import org.w3c.files.BlobPropertyBag
import org.w3c.files.FileReader
import org.w3c.files.get

object WebFileIO {
    
    /**
     * ذخیره فایل پشتیبان در دستگاه کاربر (کاملاً آفلاین با استفاده از ObjectURL)
     */
    fun downloadJsonFile(filename: String, content: String) {
        // ایجاد یک Blob از نوع JSON
        val blob = Blob(arrayOf(content), BlobPropertyBag(type = "application/json"))
        
        // اصلاح: استفاده مستقیم از W3C URL به جای window.URL
        val url = URL.createObjectURL(blob)
        
        // ایجاد یک تگ a موقت برای تریگر کردن دانلود
        val anchor = document.createElement("a") as HTMLAnchorElement
        anchor.href = url
        anchor.download = filename
        
        document.body?.appendChild(anchor)
        anchor.click()
        document.body?.removeChild(anchor)
        
        // آزادسازی حافظه کش مرورگر
        URL.revokeObjectURL(url)
    }

    /**
     * باز کردن پنجره انتخاب فایل و خواندن محتوای آن
     */
    fun importJsonFile(onResult: (String?) -> Unit) {
        val input = document.createElement("input") as HTMLInputElement
        input.type = "file"
        input.accept = ".json"
        
        input.onchange = {
            val file = input.files?.get(0)
            if (file != null) {
                val reader = FileReader()
                reader.onload = { _ ->
                    val result = reader.result as? String
                    onResult(result)
                }
                reader.onerror = {
                    console.error("خطا در خواندن فایل پشتیبان قیاس")
                    onResult(null)
                }
                reader.readAsText(file)
            } else {
                onResult(null)
            }
            null // بازگشت null برای هندلر onchange در Kotlin/JS
        }
        
        // تریگر کردن کلیک برای باز شدن پنجره انتخاب فایل
        input.click()
    }
}
